use super::*;

/// The manifest with its `[lib]` table pointing at the SHARED crate root.
///
/// Idempotent, and it REPLACES an existing `path` key rather than adding a second one — two `path`
/// keys in one table is a hard cargo error, and it would land after the source file was deleted.
/// A crate with no `[lib]` table at all gains one, because `path` has nowhere else to live.
pub fn point_lib_at_shared_root(cargo_toml: &str, crate_dir: &str) -> String {
    point_root_at_shared_root(cargo_toml, crate_dir, "lib.rs", "")
}
